import datetime as _dt


def add_years(d: _dt.date, n: int, convention: str) -> _dt.date:
    """Add n years to d. convention: 'clamp' (Feb 29 -> Feb 28) or 'roll' (Feb 29 -> Mar 1)."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n < 0:
        raise ValueError("negative years are not allowed")
    if convention not in ("clamp", "roll"):
        raise ValueError("convention must be 'clamp' or 'roll'")
    try:
        return d.replace(year=d.year + n)
    except ValueError:  # only possible when d is Feb 29 and target year isn't leap
        if convention == "roll":
            return d.replace(year=d.year + n, month=3, day=1)
        return d.replace(year=d.year + n, day=28)


def sol_simple(accrual: _dt.date, years: int) -> _dt.date:
